document.addEventListener("DOMContentLoaded", function () {

    /* Thu - Chi hoc phi (stacked bar) */
    if (document.querySelector("#reports")) {
        var chartFinance = {
            series: [
                { name: "Thu hoc phi", data: [180, 210, 195, 240, 220, 260, 230, 250, 280, 265, 290, 310] },
                { name: "Chi phi dao tao", data: [-120, -135, -128, -145, -140, -155, -148, -160, -170, -165, -175, -180] }
            ],
            chart: {
                toolbar: { show: false },
                type: "bar",
                fontFamily: "inherit",
                foreColor: "#adb0bb",
                height: 370,
                stacked: true,
                offsetX: -15
            },
            colors: ["var(--bs-success)", "rgba(155, 171, 187, .25)"],
            plotOptions: {
                bar: {
                    horizontal: false,
                    barHeight: "80%",
                    columnWidth: "20%",
                    borderRadius: [3]
                }
            },
            dataLabels: { enabled: false },
            legend: {
                show: true,
                position: "top",
                horizontalAlign: "right"
            },
            grid: {
                show: true,
                strokeDashArray: 3,
                padding: { top: 0, bottom: 0, right: 0 },
                borderColor: "rgba(0,0,0,0.05)",
                xaxis: { lines: { show: true } },
                yaxis: { lines: { show: false } }
            },
            yaxis: {
                tickAmount: 4,
                labels: {
                    show: true,
                    formatter: function (val) {
                        return val + " tr";
                    }
                }
            },
            xaxis: {
                axisBorder: { show: false },
                axisTicks: { show: false },
                categories: ["T1", "T2", "T3", "T4", "T5", "T6", "T7", "T8", "T9", "T10", "T11", "T12"]
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return Math.abs(val) + " trieu dong";
                    }
                }
            }
        };
        new ApexCharts(document.querySelector("#reports"), chartFinance).render();
    }

    /* Ty le thu hoc phi (radial bar) */
    if (document.querySelector("#cashflow")) {
        var chartCollection = {
            series: [84],
            chart: {
                type: "radialBar",
                offsetY: -20,
                sparkline: { enabled: true }
            },
            plotOptions: {
                radialBar: {
                    startAngle: -90,
                    endAngle: 90,
                    hollow: { size: "75%", position: "front" },
                    track: {
                        background: ["rgba(42, 118, 244, .18)"],
                        strokeWidth: "80%",
                        opacity: 0.5,
                        margin: 5,
                        lineCap: "round"
                    },
                    dataLabels: {
                        name: { show: false },
                        value: {
                            offsetY: -2,
                            fontSize: "20px",
                            formatter: function (val) {
                                return val + "%";
                            }
                        }
                    }
                }
            },
            stroke: { lineCap: "round" },
            colors: ["var(--bs-primary)"],
            grid: { padding: { top: -10 } },
            labels: ["Ty le thu hoc phi"]
        };
        new ApexCharts(document.querySelector("#cashflow"), chartCollection).render();
    }

    /* Phan bo sinh vien theo he (donut) */
    if (document.querySelector("#balance")) {
        var chartTrainingLevel = {
            chart: { height: 280, type: "donut" },
            plotOptions: { pie: { donut: { size: "80%" } } },
            dataLabels: { enabled: false },
            stroke: { show: true, width: 2, colors: ["transparent"] },
            series: [42, 28, 18, 12],
            legend: {
                show: true,
                position: "bottom",
                horizontalAlign: "center",
                fontSize: "13px",
                offsetX: 0,
                offsetY: 0
            },
            labels: ["Cao dang", "Trung cap", "Lien thong", "Khac"],
            colors: ["#0e2a89", "#22b783", "#ffb600", "#47cdea"],
            responsive: [{
                breakpoint: 600,
                options: {
                    plotOptions: { donut: { customScale: 0.2 } },
                    chart: { height: 240 },
                    legend: { show: false }
                }
            }],
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " %";
                    }
                }
            }
        };
        new ApexCharts(document.querySelector("#balance"), chartTrainingLevel).render();
    }

    /* Xu huong tuyen sinh (area) */
    if (document.querySelector("#chartEnrollment")) {
        var chartEnrollment = {
            series: [{
                name: "Ho so dang ky",
                data: [68, 82, 95, 110, 128, 156]
            }, {
                name: "Ho so duyet",
                data: [52, 64, 78, 88, 102, 124]
            }],
            chart: {
                height: 320,
                type: "area",
                toolbar: { show: false },
                fontFamily: "inherit",
                foreColor: "#adb0bb"
            },
            colors: ["var(--bs-primary)", "var(--bs-success)"],
            dataLabels: { enabled: false },
            stroke: { curve: "smooth", width: 2 },
            fill: {
                type: "gradient",
                gradient: {
                    shadeIntensity: 1,
                    opacityFrom: 0.4,
                    opacityTo: 0.05,
                    stops: [0, 90, 100]
                }
            },
            legend: {
                show: true,
                position: "top",
                horizontalAlign: "right"
            },
            grid: {
                strokeDashArray: 3,
                borderColor: "rgba(0,0,0,0.05)"
            },
            xaxis: {
                categories: ["T1/2025", "T2/2025", "T3/2025", "T4/2025", "T5/2025", "T6/2025"],
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            yaxis: {
                tickAmount: 4,
                labels: {
                    formatter: function (val) {
                        return Math.round(val);
                    }
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " ho so";
                    }
                }
            }
        };
        new ApexCharts(document.querySelector("#chartEnrollment"), chartEnrollment).render();
    }

    /* Hoat dong tuan (sparkline bar) */
    if (document.querySelector("#chartActivity")) {
        var chartActivity = {
            series: [{
                name: "Hoat dong",
                data: [12, 18, 15, 22, 19, 28, 24]
            }],
            chart: {
                height: 120,
                type: "bar",
                sparkline: { enabled: true },
                fontFamily: "inherit"
            },
            colors: ["var(--bs-primary)"],
            plotOptions: {
                bar: {
                    columnWidth: "45%",
                    borderRadius: 3
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " su kien";
                    }
                }
            }
        };
        new ApexCharts(document.querySelector("#chartActivity"), chartActivity).render();
    }

});

